<script setup lang="ts">import{ref}from'vue';import{boxes,cards,type BlindBox}from'../data';import DrawModal from'../components/DrawModal.vue';const box:BlindBox=boxes[0],chosen=ref<BlindBox|null>(null),count=ref(1);function draw(n:number){chosen.value=box;count.value=n}const tiers=[{name:'一等奖',chance:'1.00%',items:[cards[0]]},{name:'二等奖',chance:'5.00%',items:[cards[1],cards[2]]},{name:'三等奖',chance:'14.00%',items:[cards[2],cards[1]]}]</script>
